import React, { useState, useEffect } from 'react';
import { Search, TrendingUp, Clock, Tag } from 'lucide-react';

const Analytics = () => {
  const [stats, setStats] = useState(null);
  const [trending, setTrending] = useState([]);
  const [quality, setQuality] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        setLoading(true);

        // 并行获取统计数据
        const [statsRes, trendingRes, qualityRes] = await Promise.all([
          fetch('/api/analytics/stats'),
          fetch('/api/analytics/trending?limit=10'),
          fetch('/api/analytics/quality')
        ]);

        const [statsData, trendingData, qualityData] = await Promise.all([
          statsRes.json(),
          trendingRes.json(),
          qualityRes.json()
        ]);

        if (statsData.success) setStats(statsData.data);
        if (trendingData.success) setTrending(trendingData.data);
        if (qualityData.success) setQuality(qualityData.data);
      } catch (error) {
        console.error('获取分析数据失败:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchAnalytics();
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
        <span className="ml-2 text-gray-600">加载数据分析中...</span>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* 页面标题 */}
      <div>
        <h1 className="text-3xl font-bold text-gray-900">数据分析</h1>
        <p className="text-gray-600 mt-2">AI资讯平台运营数据分析</p>
      </div>

      {/* 统计卡片 */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <div className="flex items-center">
              <div className="p-2 bg-blue-100 rounded-lg">
                <TrendingUp className="w-6 h-6 text-blue-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">总资讯数</p>
                <p className="text-2xl font-bold text-gray-900">{stats.total}</p>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <div className="flex items-center">
              <div className="p-2 bg-green-100 rounded-lg">
                <Clock className="w-6 h-6 text-green-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">今日新增</p>
                <p className="text-2xl font-bold text-gray-900">{stats.today}</p>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <div className="flex items-center">
              <div className="p-2 bg-purple-100 rounded-lg">
                <Tag className="w-6 h-6 text-purple-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">资讯分类</p>
                <p className="text-2xl font-bold text-gray-900">{Object.keys(stats.categories || {}).length}</p>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <div className="flex items-center">
              <div className="p-2 bg-orange-100 rounded-lg">
                <Clock className="w-6 h-6 text-orange-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">最后更新</p>
                <p className="text-sm font-bold text-gray-900">
                  {stats.lastUpdate ? new Date(stats.lastUpdate).toLocaleDateString('zh-CN') : '未知'}
                </p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 分类统计 */}
      {stats?.categories && (
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">分类统计</h2>
          <div className="space-y-4">
            {Object.entries(stats.categories).map(([category, count]) => (
              <div key={category} className="flex items-center justify-between">
                <span className="text-gray-700">{category}</span>
                <div className="flex items-center">
                  <div className="w-32 bg-gray-200 rounded-full h-2 mr-4">
                    <div 
                      className="bg-blue-600 h-2 rounded-full" 
                      style={{ 
                        width: `${Math.max((count / stats.total) * 100, 5)}%` 
                      }}
                    ></div>
                  </div>
                  <span className="text-sm font-medium text-gray-900">{count}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 热门话题 */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
        <h2 className="text-xl font-semibold text-gray-900 mb-4">热门话题</h2>
        {trending.length > 0 ? (
          <div className="flex flex-wrap gap-2">
            {trending.map((topic, index) => (
              <span
                key={topic.keyword}
                className="inline-flex items-center px-3 py-2 bg-gray-100 text-gray-800 rounded-lg text-sm"
              >
                <span className="w-6 h-6 bg-blue-600 text-white rounded-full flex items-center justify-center text-xs mr-2">
                  {index + 1}
                </span>
                {topic.keyword}
                <span className="ml-2 text-gray-500">({topic.count})</span>
              </span>
            ))}
          </div>
        ) : (
          <p className="text-gray-500">暂无热门话题数据</p>
        )}
      </div>

      {/* 内容质量分析 */}
      {quality && (
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">内容质量分析</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="text-center p-4 bg-gray-50 rounded-lg">
              <p className="text-2xl font-bold text-gray-900">{quality.totalArticles}</p>
              <p className="text-sm text-gray-500">总文章数</p>
            </div>
            <div className="text-center p-4 bg-gray-50 rounded-lg">
              <p className="text-2xl font-bold text-green-600">{quality.withImages}</p>
              <p className="text-sm text-gray-500">含图片文章</p>
            </div>
            <div className="text-center p-4 bg-gray-50 rounded-lg">
              <p className="text-2xl font-bold text-blue-600">{quality.withDescriptions}</p>
              <p className="text-sm text-gray-500">含详细描述</p>
            </div>
            <div className="text-center p-4 bg-gray-50 rounded-lg">
              <p className="text-2xl font-bold text-purple-600">{quality.avgDescriptionLength}</p>
              <p className="text-sm text-gray-500">平均描述长度</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Analytics;
